package org.jsoup.select;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.TokenQueue;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class QueryParser_parse_TriageGen1Test {

    @Test
    public void testParse_NullQuery() {
        QueryParser parser = new QueryParser(null);
        try {
            parser.parse();
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testParse_EmptyQuery() {
        QueryParser parser = new QueryParser("");
        Evaluator result = parser.parse();
        assertNull(result);
    }

    @Test
    public void testParse_SimpleQuery() {
        QueryParser parser = new QueryParser("div");
        Evaluator result = parser.parse();
        assertNotNull(result);
    }

    @Test
    public void testParse_ComplexQuery() {
        QueryParser parser = new QueryParser("div.class > span.id");
        Evaluator result = parser.parse();
        assertNotNull(result);
    }

    @Test
    public void testParse_QueryWithPunctuation() {
        QueryParser parser = new QueryParser("div.class > span.id;");
        Evaluator result = parser.parse();
        assertNotNull(result);
    }

    @Test
    public void testParse_QueryWithWhitespace() {
        QueryParser parser = new QueryParser("div.class > span.id  ");
        Evaluator result = parser.parse();
        assertNotNull(result);
    }

    @Test
    public void testParse_QueryWithSpecialChar() {
        QueryParser parser = new QueryParser("div@class > span#id");
        Evaluator result = parser.parse();
        assertNotNull(result);
    }

    @Test
    public void testParse_QueryWithEscapeChar() {
        QueryParser parser = new QueryParser("div\\.class > span\\#id");
        Evaluator result = parser.parse();
        assertNotNull(result);
    }
}
